{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret konkluderer 'Ja' og siger, at alle syv faktorer indgår i vurderingen af erhvervsevnen. Det er stik imod kilden og rubrikken: arbejdsprøvning, særlig arbejdspladsindretning, arbejdsgiverkontakt, studierelevans, lokale forhold, jobmuligheder og erhvervsevne efter uddannelsen indgår ikke. Kommunal arbejdsevnevurdering er heller ikke målestokken. Der er flere væsentlige materielle fejl."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Ingen af de kritiske elementer er med. Svaret angiver ikke målestokken (evne til erhvervsarbejde som uddannelsessøgende ud fra funktionsnedsættelsens art og grad). Det siger ikke, at vurderingen er adskilt fra den kommunale arbejdsevnevurdering, og at arbejdsprøvning, indretning og arbejdsgiverkontakt er udelukket. Det udelukker ikke studierelevans, lokale forhold og beskæftigelsessituation, og det afviser ikke erhvervsevnen efter uddannelsen som målestok. Alle er i stedet gjort til indgående faktorer."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret behandler hver af de syv nævnte faktorer enkeltvis og forholder sig direkte til spørgsmålet, selv om indholdet er forkert."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (lov, bekendtgørelse eller vejledning)."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så støtte for påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer retsregler uden støtte i materialet og i modstrid med det. Det hævder, at arbejdsprøvning, indretning, arbejdsgiverkontakt, studierelevans, lokale jobmuligheder og erhvervsevne efter uddannelsen indgår. Det tilføjer også, at 'uddannelsesmæssige og personlige forudsætninger' vurderes sammen med sundhedstilstanden."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret bevarer ikke de afgørende begrænsninger. Vejledningen siger, at vurderingen alene angår erhvervsevne som uddannelsessøgende og ikke erhvervsevnen efter uddannelsen, og at flere elementer udtrykkeligt ikke indgår. Svaret nævner ingen af disse udelukkelser. Kravet om varig funktionsnedsættelse og meget betydelige begrænsninger er heller ikke med."},
    "c09_reasoning_coherence": {"label": "not_met", "reason": "Svaret er internt konsistent i sin opremsning, men begrundelsen bygger på den forkerte præmis, at alle faktorerne indgår. Den kommunale arbejdsevnevurdering sidestilles med erhvervsevnevurderingen. Beskrivelsen af 'erhvervsevnen efter uddannelsen' modsiger, at vurderingen kun angår erhvervsevne som uddannelsessøgende. Konklusionen følger ikke af de gældende regler."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret gør udelukkede elementer til faste led i vurderingen ('Ja, ... indgår'). Det erstatter dermed en udelukkelse med en positiv regel."}
  },
  "xhaile_coverage": {
    "A15": {"label": "no", "reason": "Svaret gengiver ikke indholdet i punktet: at der kun tages stilling til evnen til erhvervsarbejde som uddannelsessøgende med de ressourcer, personen har, og at arbejdsprøvning, indretning, arbejdsgiverkontakt, studierelevans, lokale forhold og erhvervsevne efter uddannelsen ikke indgår. Svaret påstår det modsatte. Det nævner heller ikke kravet om meget betydelige begrænsninger."}
  },
  "overall_notes": "Svaret er direkte rettet mod spørgsmålet, men juridisk forkert. Det bekræfter alle syv faktorer, hvor kilden udelukker dem, og angiver ingen kilder."
}

